import { test, expect } from '@playwright/test';

test.describe('Secure Area Login - Returning User', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in a returning user and navigate to secure area with success flash banner', async ({ page }) => {
    // Setup: intercept the login API call
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Intercept the successful response
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Intercept the redirect to secure area
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Locate and fill in username and password fields
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('tomsmith');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SuperSecretPassword!');

    // Locate and click the submit button
    const loginButton = page.getByRole('button', { name: /submit/i });
    await loginButton.click();

    // Wait for navigation to complete
    await page.waitForURL('**/secure');

    // Verify the URL contains '/secure'
    const secureUrl = page.url();
    expect(secureUrl).toContain('/secure');

    // Verify the success flash banner is visible
    const successFlash = page.getByText('You logged into a secure area!');
    await expect(successFlash).toBeVisible();

    // Verify the page content is as expected
    const secureContent = page.getByText('Secure Area Content');
    await expect(secureContent).toBeVisible();
  });

  test('should display error message when login fails due to invalid credentials', async ({ page }) => {
    // Setup: intercept the login API call
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Locate and fill in username and password fields
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('invaliduser');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('WrongPassword!');

    // Locate and click the submit button
    const loginButton = page.getByRole('button', { name: /submit/i });
    await loginButton.click();

    // Wait for error message to appear
    const errorMessage = page.getByText('Invalid username or password');
    await expect(errorMessage).toBeVisible();

    // Verify the page does not navigate to secure area
    const secureUrl = page.url();
    expect(secureUrl).not.toContain('/secure');

    // Verify the error message is displayed
    await expect(errorMessage).toBeVisible();
  });
});
